// @generated by:gauntlet run:godseye-local-database
import { randomUUID } from "node:crypto";
import type { CreateEnvironmentInput, ProjectView } from "@godseye/contracts";
import { ControlPlane } from "@godseye/core";
import { openStore, type Store } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { owner, projectInput } from "./helpers.js";

const day = 86_400_000;
function preview(revision = 0): CreateEnvironmentInput {
  return {
    expectedProjectRevision: revision,
    name: "review-branch",
    kind: "preview",
    expiresAt: new Date(Date.now() + day).toISOString(),
    memoryMiB: 256,
    cpuMilliCores: 250,
    diskGiB: 2,
  };
}
describe("revision-safe project and persistent preview lifecycle", () => {
  let store: Store;
  let core: ControlPlane;
  let project: ProjectView;
  beforeEach(async () => {
    store = await openStore();
    core = new ControlPlane(store);
    project = await core.createProject(owner, projectInput, randomUUID());
  });
  afterEach(async () => store.close());

  it("T-AC-27 replays a rename once without changing identity or inventing resources", async () => {
    const input = {
        expectedRevision: project.revision,
        name: "Renamed observatory",
        description: "Updated metadata",
      },
      key = randomUUID();
    const [first, replay] = await Promise.all([
      core.updateProject(owner, project.id, input, key),
      core.updateProject(owner, project.id, input, key),
    ]);
    expect(first).toEqual(replay);
    expect(first).toMatchObject({
      id: project.id,
      slug: project.slug,
      name: input.name,
      revision: 1,
      status: "draft",
    });
    expect(first.environments).toEqual(project.environments);
    expect(
      (await core.listAudit(owner)).filter((row) => row.action === "project.updated"),
    ).toHaveLength(1);
  });

  it("T-AC-27 refuses stale rename and changed idempotency payload without overwriting the winner", async () => {
    const input = {
        expectedRevision: project.revision,
        name: "Accepted rename",
        description: "Accepted",
      },
      key = randomUUID();
    await core.updateProject(owner, project.id, input, key);
    await expect(
      core.updateProject(owner, project.id, { ...input, name: "Changed key" }, key),
    ).rejects.toMatchObject({ status: 409, code: "IDEMPOTENCY_CONFLICT" });
    await expect(
      core.updateProject(owner, project.id, { ...input, name: "Stale rename" }, randomUUID()),
    ).rejects.toMatchObject({ status: 409, code: "REVISION_CONFLICT" });
    expect(await core.getProject(owner, project.id)).toMatchObject({
      name: input.name,
      revision: 1,
    });
  });

  it("T-AC-27 admits one winner for competing revision-bound renames", async () => {
    const results = await Promise.allSettled(
      ["First candidate", "Second candidate"].map((name) =>
        core.updateProject(
          owner,
          project.id,
          { expectedRevision: 0, name, description: "" },
          randomUUID(),
        ),
      ),
    );
    expect(results.filter((result) => result.status === "fulfilled")).toHaveLength(1);
    expect(results.filter((result) => result.status === "rejected")).toHaveLength(1);
    expect((await core.getProject(owner, project.id)).revision).toBe(1);
  });

  it("T-AC-27 registers one named bounded persistent preview under concurrent replay", async () => {
    const input = preview(),
      key = randomUUID();
    const [first, replay] = await Promise.all([
      core.createEnvironment(owner, project.id, input, key),
      core.createEnvironment(owner, project.id, input, key),
    ]);
    expect(first).toEqual(replay);
    expect(first.environments).toHaveLength(3);
    expect(first.environments.find((env) => env.kind === "preview")).toMatchObject({
      name: input.name,
      expiresAt: input.expiresAt,
      revision: 0,
      status: "planned",
      requestedState: null,
      memoryMiB: input.memoryMiB,
    });
    expect(first.environments.filter((env) => env.kind !== "preview")).toEqual(
      project.environments,
    );
  });

  it.each(["past", "beyond-limit", "invalid"] as const)(
    "T-AC-27 rejects a %s preview expiry without leaving a partial registration",
    async (mode) => {
      const expiresAt =
        mode === "invalid"
          ? "never"
          : new Date(Date.now() + (mode === "past" ? -day : 31 * day)).toISOString();
      await expect(
        core.createEnvironment(owner, project.id, { ...preview(), expiresAt }, randomUUID()),
      ).rejects.toMatchObject({ status: 422 });
      expect((await core.getProject(owner, project.id)).environments).toHaveLength(2);
      expect((await core.getProject(owner, project.id)).revision).toBe(0);
    },
  );

  it("T-AC-27 enforces preview name uniqueness and an atomic finite preview count", async () => {
    let current = await core.createEnvironment(owner, project.id, preview(), randomUUID());
    await expect(
      core.createEnvironment(owner, project.id, preview(current.revision), randomUUID()),
    ).rejects.toMatchObject({ status: 409 });
    for (let index = 1; index < 8; index++)
      current = await core.createEnvironment(
        owner,
        project.id,
        { ...preview(current.revision), name: `review-${index}` },
        randomUUID(),
      );
    await expect(
      core.createEnvironment(
        owner,
        project.id,
        { ...preview(current.revision), name: "ninth-preview" },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect(
      (await core.getProject(owner, project.id)).environments.filter(
        (env) => env.kind === "preview",
      ),
    ).toHaveLength(8);
  });

  it("T-AC-27 binds environment edits to both revisions and preserves actual lifecycle honesty", async () => {
    const environment = project.environments[0];
    if (!environment) throw new Error("Missing environment fixture");
    const input = {
      expectedProjectRevision: project.revision,
      expectedRevision: environment.revision,
      name: "renamed-development",
      expiresAt: null,
      memoryMiB: 512,
      cpuMilliCores: 500,
      diskGiB: 4,
    };
    const updated = await core.updateEnvironment(
      owner,
      project.id,
      environment.id,
      input,
      randomUUID(),
    );
    expect(updated.environments.find((env) => env.id === environment.id)).toMatchObject({
      name: input.name,
      revision: 1,
      status: "planned",
      requestedState: null,
      memoryMiB: input.memoryMiB,
    });
    await expect(
      core.updateEnvironment(
        owner,
        project.id,
        environment.id,
        { ...input, expectedProjectRevision: updated.revision },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409, code: "REVISION_CONFLICT" });
    await expect(
      core.requestOperation(
        owner,
        project.id,
        { action: "project.suspend", expectedRevision: updated.revision },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 503 });
    expect((await core.getProject(owner, project.id)).status).toBe("draft");
  });

  it("T-AC-27 denies foreign environment ancestry and application metadata authority", async () => {
    const other = await core.createProject(
      owner,
      { ...projectInput, slug: "other-project" },
      randomUUID(),
    );
    const environment = project.environments[0];
    if (!environment) throw new Error("Missing environment fixture");
    const input = {
      expectedProjectRevision: other.revision,
      expectedRevision: environment.revision,
      name: "foreign-environment",
      expiresAt: null,
      memoryMiB: 512,
      cpuMilliCores: 500,
      diskGiB: 4,
    };
    await expect(
      core.updateEnvironment(owner, other.id, environment.id, input, randomUUID()),
    ).rejects.toMatchObject({ status: 403 });
    const service = { id: "application", kind: "service" as const, projectIds: [project.id] };
    await expect(
      core.updateProject(
        service,
        project.id,
        { expectedRevision: 0, name: "Service rename", description: "" },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 403 });
    await expect(
      core.createEnvironment(service, project.id, preview(), randomUUID()),
    ).rejects.toMatchObject({ status: 403 });
    expect((await core.getProject(owner, project.id)).revision).toBe(0);
  });
});
